				Destination: &ival,
			},
		},...", "path": "docs/v3/examples/arguments/advanced.md", "retrieval_provenance": {"blob_sha": "2c1945232f3a6f9f7a4be0d113286fe8ed7f2cd2", "discovery_source": "base_sha_tree", "excluded_artifact_paths": 11, "generator_pool_policy": "base_sha_broad_bounded_doc_pool_v2", "max_generator_doc_chars_per_file": 1500, "max_generator_doc_files": 12, "method": "base_sha_tree_documentation_discovery_v2", "path": "docs/v3/examples/arguments/advanced.md", "selection_policy": "prefer_first_party_human_docs_then_root_project_docs_then_reference_plus_neutral_code_path_affinity", "selection_rank": 1, "selection_score": [45, 2, 5, 5, "docs/v3/examples/arguments/advanced.md"], "tree_discovery_succeeded": true, "tree_ref": "78e356c8ef99e4c360ad82118ed5089f2309975b", "truncated": false, "truncated_excerpt": true, "used_docs_changed_files": false}, "source_ref": "78e356c8ef99e4c360ad82118ed5089f2309975b"}, {"blob_sha": "ddde3a4779ba18d920df5664fc44fe00e2adecd3", "excerpt": "---
