					fmt.Println("completed tas...", "path": "docs/v3/examples/completions/shell-completions.md", "retrieval_provenance": {"blob_sha": "b355a6320f715760a41228cb42e0b77d88e7c6ba", "discovery_source": "base_sha_tree", "excluded_artifact_paths": 11, "generator_pool_policy": "base_sha_broad_bounded_doc_pool_v2", "max_generator_doc_chars_per_file": 1500, "max_generator_doc_files": 12, "method": "base_sha_tree_documentation_discovery_v2", "path": "docs/v3/examples/completions/shell-completions.md", "selection_policy": "prefer_first_party_human_docs_then_root_project_docs_then_reference_plus_neutral_code_path_affinity", "selection_rank": 4, "selection_score": [45, 3, 5, 5, "docs/v3/examples/completions/shell-completions.md"], "tree_discovery_succeeded": true, "tree_ref": "6a8503dc6e59e427ab108ee20361b9845949e0ec", "truncated": false, "truncated_excerpt": true, "used_docs_changed_files": false}, "source_ref": "6a8503dc6e59e427ab108ee20361b9845949e0ec"}, {"blob_sha": "e5a5fff7e5c556c07c1e99e23175e3949a3d7963", "excerpt": "---
