+                .borrow_input()
+                .validate_str(true, false)
+                .map(ValidationMatch::into_inner)
+            {
+                Ok(k) => k,
+                Err(ValError::LineErrors(line_errors)) => {
+                    for err in line_errors {
+                        self.errors.push(
+                            err.with_outer_location(raw_ke...

